// Obtenemos todos los items del input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const services = Array.isArray(root.response) ? root.response : [];
if (!services.length) {
  throw new Error('No se encontraron servicios en root.response');
}

const output = [];

for (const svc of services) {

  // 🔎 FILTRO POR "Reparación"
  if (!svc.serviceName || !svc.serviceName.toLowerCase().includes('reparación'.toLowerCase())) {
    continue;
  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
    description: svc.name ?? null,
    price,
    normalPrice: svc.servicePrice ?? null,
    isPromo: !!(promo && promo.promotionalActive),
  };

  output.push({ json: simplified });
}

return output;

// Obtenemos todos los items del input
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) throw new Error('El array raíz está vacío');
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const services = Array.isArray(root.response) ? root.response : [];
if (!services.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// 🔥 Función para normalizar texto (quita tildes y pasa a minúscula)
function normalizeText(text) {
  return text
    ?.normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase();
}

const output = [];

for (const svc of services) {

  const serviceNameNormalized = normalizeText(svc.serviceName);

  // 🔎 FILTRO ROBUSTO POR "Diagnóstico"
  if (!serviceNameNormalized || !serviceNameNormalized.includes("diagnostico")) {
    continue;
  }

  const servicesByModelGroup = Array.isArray(svc.servicesByModelGroup)
    ? svc.servicesByModelGroup
    : [];

  let promo = null;
  for (const mg of servicesByModelGroup) {
    if (mg.promotionalActive) {
      promo = mg;
      break;
    }
  }

  const price = promo && typeof promo.promotionalPrice === 'number'
    ? promo.promotionalPrice
    : svc.servicePrice ?? null;

  const simplified = {
    serviceId: svc.serviceId,
    name: svc.serviceName,
    description: svc.name ?? null,
    price,
    normalPrice: svc.servicePrice ?? null,
    isPromo: !!(promo && promo.promotionalActive),
  };

  output.push({ json: simplified });
}

return output;

// Obtenemos los items de entrada
const items = $input.all();

if (!items.length) {
  throw new Error('No hay datos de entrada');
}

// El input viene como:
// [ { httpCode, message, response: [ { ...servicio }, ... ] } ]
let root = items[0].json;

if (Array.isArray(root)) {
  if (!root.length) {
    throw new Error('El array raíz está vacío');
  }
  root = root[0];
}

if (!root || typeof root !== 'object') {
  throw new Error('Formato de entrada inválido');
}

const list = Array.isArray(root.response) ? root.response : [];
if (!list.length) {
  throw new Error('No se encontraron servicios en root.response');
}

// Helper para normalizar fechas a "solo día"
function toDateOnly(value) {
  if (!value) return null;
  const d = new Date(value);
  if (isNaN(d.getTime())) return null;
  d.setHours(0, 0, 0, 0);
  return d;
}

// Helper para parsear montos (string o number)
function toNumber(value) {
  if (value === null || value === undefined) return 0;
  if (typeof value === 'number') return value;
  const s = String(value).replace(',', '.');
  const n = Number(s);
  return isNaN(n) ? 0 : n;
}

// Fecha actual (Argentina, pero solo día nos alcanza)
const now = new Date();
now.setHours(0, 0, 0, 0);

// Filtramos servicios vigentes hoy
const vigentes = list.filter(item => {
  const start = toDateOnly(item.modelStartDate);
  const end = toDateOnly(item.modelEndDate);
  if (!start || !end) return false;
  return start <= now && now <= end;
});

if (!vigentes.length) {
  throw new Error('No hay servicios vigentes para la fecha actual');
}

// Tomamos el primero vigente (en tu caso el de diciembre)
const svc = vigentes[0];

// Calculamos precio de ítems
const parts = Array.isArray(svc.revisionPartVOs) ? svc.revisionPartVOs : [];

let totalPartsPrice = 0;
const includedItems = parts.map(p => {
  const qty = toNumber(p.quantity);
  const price = toNumber(p.price);
  const subtotal = qty * price;
  totalPartsPrice += subtotal;

  return {
    description: p.longDescription || p.shortDescription || null,
    quantity: qty,
    unitPrice: price,
    subtotal,
  };
});

// Mano de obra
const labor = toNumber(svc.costLabor);

// Precio total = mano de obra + repuestos
const totalPrice = labor + totalPartsPrice;

// Agregar items adicionales fijos
includedItems.push(
  {
    description: "Control de 25 puntos de seguridad",
    quantity: 1,
    unitPrice: 0,
    subtotal: 0,
  },
  {
    description: "Lectura de códigos de falla con scanner FORD",
    quantity: 1,
    unitPrice: 0,
    subtotal: 0,
  }
);
// Armamos salida simple
const result = {
  serviceId: svc.serviceId,
  serviceCode: svc.service,             // ej: SM01
  serviceDescription: svc.serviceDescription,
  monthService: svc.monthService,

  totalPrice,

  includes: includedItems,
};

return [
  {
    json: result,
  },
];

// km: busca primero en el trigger, luego en la base de datos, o usa 15000 por defecto para pruebas
const triggerKm = $('When Executed by Another Workflow').first().json.km;
const dbData = $('Select rows from a table2').first().json;
const dbKm = dbData.km;

// Si viene string lo parsea a número, si no viene toma 0
const kmRaw = Number(triggerKm || dbKm || 0);

// km_frequency viene de la base de datos o toma 15000 por defecto
const kmFrequency = Number(dbData.km_frequency) || 15000;

// Si km viene en 0 o null, asume el primer service (kmFrequency)
const kmEfectivo = kmRaw > 0 ? kmRaw : kmFrequency;

// Redondear km al múltiplo de km_frequency más cercano (mínimo km_frequency)
const kmRedondeado = Math.max(kmFrequency, Math.round(kmEfectivo / kmFrequency) * kmFrequency);

// Cálculo del número de servicio y meses
const serviceNumber = Math.round(kmRedondeado / kmFrequency);
const months = Math.max(12, serviceNumber * 12);

const SERVICIOS = {
  1:  1403,   // 1ª Revisión de Mantenimiento
  2:  1404,   // 2ª
  3:  1405,   // 3ª
  4:  1406,   // 4ª 
  5:  1407,   // 5ª
  6:  1408,   // 6ª
  7:  1409,   // 7ª
  8:  1410,   // 8ª
  9:  1411,   // 9ª
  10: 1412,   // 10ª
  11: 1413,   // 11ª
  12: 1414,   // 12ª
  13: 1415,   // 13ª
  14: 1416,   // 14ª
  15: 1417,   // 15ª
  16: 1418,   // 16ª
  17: 1419    // 17ª 
};

const serviceId = SERVICIOS[serviceNumber] || (1402 + serviceNumber);

return [
  {
    json: {
      km_original: kmRaw,
      km_redondeado: kmRedondeado,
      km_frequency: kmFrequency,
      service_number: serviceNumber,
      service_id: serviceId,
      months,
    }
  }
];

