// ==========================================================
// Code34 - Payload para crear el turno a partir de "Turno ofrecido" (AYALA Corrientes)
// ==========================================================
const CREATE_USER = 'A-AYAL65';
const DEALER_CODE = 128;
const NOMBRE_CONCESIONARIO = 'AYALA Corrientes';
const IDS_MANTENIMIENTO = [5, 111];

function toHourNumber(hora) { return Number(String(hora).trim().replace(':', '')); }
function cleanHHMM(hora)   { return String(hora).trim().replace(':', '').padStart(4, '0'); }
function getCreateSTimestamp() {
  const now = new Date();
  return `${now.toISOString().slice(0, 19)}.${String(now.getMilliseconds()).padStart(3, '0')}0`;
}
const norm = (v) => String(v ?? '').normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().replace(/\s+/g, ' ').trim();
const normalizarPatente = (v) => String(v ?? '').replace(/[^a-zA-Z0-9]/g, '').toUpperCase();

// 1. Nodos de origen de datos
const turno = $('Turno ofrecido').first().json;
const tabla = $('Select rows from a table4').first().json;
const trigger = $('When Executed by Another Workflow').first().json;
const cotizacionNode = $('HTTP Request33').first().json;
const especialistas = $('HTTP Request').first().json?.result?.technicalSpecialists || [];

// Si no se encontró el turno ofrecido, no creamos nada
if (turno.turnosEncontrados === 0 || !turno.horarioRecepcion) {
  throw new Error(`No se encontró el turno ofrecido: ${turno.mensaje || 'sin datos'}`);
}

// 2. Horarios y Fechas
const scheduleDate = turno.fecha;
const scheduleHourNum = toHourNumber(turno.horarioRecepcion);

// 3. Asesor de recepción
const advisorId = Number(turno.asesorId);

// 4. Mecánico y Especialidad de Taller
const mecanico = especialistas.find(e => norm(e.advisorName) === norm(turno.mecanicoNombre));
if (!mecanico) {
  throw new Error(`No se encontró el ID del mecánico "${turno.mecanicoNombre}" en el HTTP Request`);
}
const productiveId = Number(mecanico.advisorId);

const [horaInicioMec, horaFinMec] = String(turno.huecoMecanico).split(/[-–—]/).map(s => s.trim());
const productiveAttendanceHour = cleanHHMM(horaInicioMec);
const productiveAttendanceEndHour = cleanHHMM(horaFinMec);

const specialtyIds = (mecanico.specialties || []).map(s => s.id);
const serviceTypeIdWorkshop = Number(
  specialtyIds.find(id => IDS_MANTENIMIENTO.includes(id)) ?? specialtyIds[0] ?? 5
);

// 5. Cotización y Servicios Ofrecidos
const quotationScheduleVO = cotizacionNode.result?.quotationScheduleVO || cotizacionNode.quotationScheduleVO;
const serviceIdComercial = Number(quotationScheduleVO.quotationVOs[0].serviceId);

// 6. Concesionario, Vehículo y Cliente
const dealerCode = Number(tabla.sucursal) || DEALER_CODE;
const customerId = Number(tabla.customerK);
const vehiclePlate = normalizarPatente(trigger.patente || tabla.plate) || null;
const vehicleVin = tabla.chassi;
const modelGroup = Number(tabla.model_id);

const nombreCliente = [tabla.firstname, tabla.lastname].filter(Boolean).join(' ').trim();

// Km: primero "km declarados:" dentro del resumen, si no el km que mandó el trigger
const kmRaw = (String(trigger.resumen || '').match(/km declarados:\s*([\d.]+)/i) || [])[1] ?? trigger.km;
const kmDeclarados = kmRaw ? String(kmRaw).replace(/\./g, '') : null;
const lastKm = kmDeclarados ? (Number(kmDeclarados) || null) : null;

// 6c. Observaciones — customerRemark nunca null (formato: "Medio de pago: X. comentarios")
const resumen = String(trigger.resumen || '').trim();
const obsCliente = [
  resumen || 'Sin comentarios adicionales.',
  `Concesionario: ${NOMBRE_CONCESIONARIO}.`,
  vehiclePlate ? `Patente: ${vehiclePlate}.` : '',
].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();

const obsConcesionario = [
  'Turno generado por el asistente virtual de WhatsApp.',
  `Concesionario: ${NOMBRE_CONCESIONARIO}.`,
  vehiclePlate ? `Patente: ${vehiclePlate}.` : '',
  tabla.model ? `Vehículo: ${tabla.model}.` : '',
  nombreCliente ? `Cliente: ${nombreCliente}.` : '',
  kmDeclarados ? `KM declarados: ${kmDeclarados}.` : '',
].filter(Boolean).join(' ').replace(/\s+/g, ' ').trim();

// 7. Payload
const payload = {
  country: "ARG",
  dealer: dealerCode,
  scheduleDate: scheduleDate,
  scheduleHour: scheduleHourNum,
  vin: vehicleVin,
  offeredServices: [serviceIdComercial],
  quotationScheduleVO: quotationScheduleVO,
  advisor: advisorId,
  createUser: CREATE_USER,
  sendEmail: true,
  contactCountry: "ARG",
  vehiclePlate: vehiclePlate,
  contactCustomerId: customerId,
  customerId: customerId,
  customerRemark: obsCliente,
  advisorRemark: obsConcesionario,
  isDriverInformation: null,
  scheduleSource: "D",
  scheduleType: "R",
  model: "",
  group: modelGroup,
  createS: getCreateSTimestamp(),
  campaignsId: [],
  lastKm: lastKm,
  oilLifeRemaining: null,
  iolmMonths: null,
  referredBy: 0,
  scheduleWorkshop: [
    {
      openSchedule: false,
      noShow: false,
      productiveId: productiveId,
      productiveAttendanceHour: productiveAttendanceHour,
      productiveAttendanceEndHour: productiveAttendanceEndHour,
      productiveAttendance: scheduleDate,
      assignedService: [{ id: serviceTypeIdWorkshop, duration: 60 }],
      status: "SCHEDULED",
      statusSchedule: "SCHEDULED",
      delay: false,
      height: 138.88888888888889
    }
  ]
};

return [{ json: { body: payload } }];

const fechaActual = $('Select rows from a table4').first().json.selected_date

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

const data = $input.first().json.result;
const specialists = data?.technicalSpecialists || [];
const schedules = data?.schedules || [];
const resultado = [];

for (const esp of specialists) {
  const specialtyIds = (esp.specialties || []).map(s => s.id);

  const firstShift = esp.workSchedule?.firstShift;
  const secondShift = esp.workSchedule?.secondShift;

  // Si está totalmente no disponible o no tiene turnos configurados
  if (esp.availability?.totallyUnavailable || (!firstShift && !secondShift)) {
    resultado.push({
      json: {
        fechaActual,
        advisorName: esp.advisorName,
        Huecos_Libres: [],
        specialtyIds
      }
    });
    continue;
  }

  // Obtenemos los bloqueos de indisponibilidad (soporta unavailableTimes y unavailablePeriods)
  const unavailableList = esp.availability?.unavailableTimes || esp.availability?.unavailablePeriods || [];

  const bloqueosIndisponibilidad = unavailableList
    .map(p => {
      const ini = toMinutes(p.startTime || p.start || p.entry);
      const fin = toMinutes(p.endTime || p.end || p.exit);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Obtenemos las citas ya agendadas
  const citasAgendadas = schedules
    .filter(s => s.productiveId === esp.advisorId || s.advisorId === esp.advisorId)
    .map(s => {
      const ini = toMinutes(s.startTime || s.start);
      const fin = toMinutes(s.endTime || s.end);
      return (ini !== null && fin !== null) ? [ini, fin] : null;
    })
    .filter(Boolean);

  // Unificamos y ordenamos todos los intervalos ocupados
  const ocupados = [...bloqueosIndisponibilidad, ...citasAgendadas].sort((a, b) => a[0] - b[0]);

  const turnosTrabajo = [];
  if (firstShift?.entry && firstShift?.exit) {
    turnosTrabajo.push([toMinutes(firstShift.entry), toMinutes(firstShift.exit)]);
  }
  if (secondShift?.entry && secondShift?.exit) {
    turnosTrabajo.push([toMinutes(secondShift.entry), toMinutes(secondShift.exit)]);
  }

  const huecos = [];
  for (const [inicioTurno, finTurno] of turnosTrabajo) {
    let cursor = inicioTurno;
    for (const [ini, fin] of ocupados) {
      if (fin <= cursor || ini >= finTurno) continue;
      if (ini > cursor) {
        huecos.push([cursor, Math.min(ini, finTurno)]);
      }
      cursor = Math.max(cursor, fin);
    }
    if (cursor < finTurno) {
      huecos.push([cursor, finTurno]);
    }
  }

  resultado.push({
    json: {
      fechaActual,
      advisorName: esp.advisorName,
      Huecos_Libres: huecos.map(([ini, fin]) => `${toHHMM(ini)} - ${toHHMM(fin)}`),
      specialtyIds
    }
  });
}

return resultado;

// ─── CONFIG ───────────────────────────────────────────────────────────────
const TIPOS_QUE_OCUPAN     = ["SCHEDULED"];
const RESPETAR_DIAS_LIBRES = true;
// ──────────────────────────────────────────────────────────────────────────

function normFecha(v) {
  if (!v) return null;
  if (v instanceof Date) return isNaN(v) ? null : v.toISOString().slice(0, 10);
  const m = String(v).trim().match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : null;
}

// Fecha del turno elegido por el cliente (rama create_turno)
let fechaActual = normFecha($('Select rows from a table4').first().json.selected_date);

const toMinutes = (hhmm) => {
  if (!hhmm) return null;
  const [h, m] = String(hhmm).trim().split(':').map(Number);
  return Number.isNaN(h) || Number.isNaN(m) ? null : h * 60 + m;
};
const toHHMM = (mins) =>
  `${String(Math.floor(mins / 60)).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')}`;
const normHora = (h) => { const m = toMinutes(h); return m === null ? null : toHHMM(m); };

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry), fin = toMinutes(exit);
  if (inicio === null || fin === null || !(interval > 0)) return [];
  const slots = [];
  for (let t = inicio; t < fin; t += interval) slots.push(toHHMM(t));
  return slots;
}

// Junta asesores de todos los items, sin duplicar
const advisorsMap = new Map();
let interval = 30;
for (const item of $input.all()) {
  const d = item?.json?.result?.advisorDealerSchedule;
  if (!d) continue;
  interval = Number(d.interval) || interval;
  for (const a of d.advisors || []) if (!advisorsMap.has(a.advisorId)) advisorsMap.set(a.advisorId, a);
}
const advisors = [...advisorsMap.values()];

// Sin fecha válida no se puede calcular nada: se corta acá con un mensaje claro
if (!fechaActual) {
  return [{
    json: {
      fechaActual: null,
      vacio: true,
      Slots_Libres: [],
      Cantidad_Slots_Libres: 0,
      error: 'selected_date vacío o con formato inválido en agenda_ford',
      selected_date_raw: $('Select rows from a table4').first().json.selected_date ?? null,
    },
  }];
}

const resultado = advisors.map((a) => {
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval),
  ];

  // Bloqueados (francos / ausencias vigentes ese día)
  const bloqueados = new Set();
  if (RESPETAR_DIAS_LIBRES) {
    const offs = (a.daysOffs || []).filter((o) => {
      const ini = normFecha(o.startDay), fin = normFecha(o.endDay);
      return (!ini || fechaActual >= ini) && (!fin || fechaActual <= fin);
    });
    if (offs.some((o) => o.allDay)) {
      gridCompleto.forEach((s) => bloqueados.add(s));
    } else {
      offs.forEach((o) => {
        if (o.offStartHour && o.offEndHour) {
          generarSlots(o.offStartHour, o.offEndHour, interval).forEach((s) => bloqueados.add(s));
        }
      });
    }
  }

  // Ocupados: solo citas SCHEDULED de ese día
  const ocupados = new Set();
  (a.dealerSchedule || []).forEach((c) => {
    if (!TIPOS_QUE_OCUPAN.includes(String(c.typeOfSchedule || '').toUpperCase())) return;
    const f = normFecha(c.dateSchedule);
    if (f && f !== fechaActual) return;
    const h = normHora(c.hourSchedule);
    if (h) ocupados.add(h);
  });

  // Passerby: no ocupa, solo etiqueta
  const sinCita = new Set((a.nonScheduled || []).map((s) => normHora(s.passerbyHour)).filter(Boolean));

  const ofrecibles = gridCompleto
    .filter((hora) => !bloqueados.has(hora) && !ocupados.has(hora))
    .map((hora) => ({ hora, estado: sinCita.has(hora) ? 'LIBRE_SIN_CITA' : 'LIBRE' }));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: String(a.advisorName || '').replace(/\s+/g, ' ').trim(),
      Slots_Libres: ofrecibles.map((g) => g.hora),
      Cantidad_Slots_Libres: ofrecibles.length,
      Slots_Libres_Puros: ofrecibles.filter((g) => g.estado === 'LIBRE').map((g) => g.hora),
      Slots_Sin_Cita: ofrecibles.filter((g) => g.estado === 'LIBRE_SIN_CITA').map((g) => g.hora),
      Grilla: ofrecibles,
    },
  };
});

if (resultado.length === 0) {
  return [{ json: { fechaActual, vacio: true, Slots_Libres: [], Cantidad_Slots_Libres: 0 } }];
}
return resultado;

const items = $input.all().map(i => i.json);

function toMinutes(hhmm) {
  if (!hhmm) return null;
  const [h, m] = hhmm.trim().split(':').map(Number);
  return h * 60 + m;
}

function toHHMM(minutes) {
  const h = Math.floor(minutes / 60).toString().padStart(2, '0');
  const m = (minutes % 60).toString().padStart(2, '0');
  return `${h}:${m}`;
}

const MAPA_SERVICIOS = {
  5: 'Mantenimiento',
  14: 'Taller Móvil',
  111: 'Mantenimiento - Kit IOLM',
  112: 'Reparación',
  113: 'Campañas De Servicio',
  114: 'Diagnóstico',
  115: 'Servicios Generales',
  116: 'Accesorios',
  117: 'Lavado',
  118: 'Colisión'
};

// Ids de specialty que cuentan como "hace Mantenimiento"
const IDS_MANTENIMIENTO = [5, 111];

const DURACION_TURNO_MINUTOS = 60;
const HORA_APERTURA = toMinutes('08:00');
const HORA_CIERRE   = toMinutes('17:00'); // último turno posible: 16:00-17:00

const resultado = [];

for (const item of items) {
  const fecha = item.fechaActual || item.fecha;
  const advisorName = item.advisorName || item.mecanicoNombre;
  const huecosEntrada = item.Huecos_Libres || item.huecosLibres || [];

  let servicios = item.servicios || [];
  if (servicios.length === 0 && Array.isArray(item.specialtyIds)) {
    servicios = item.specialtyIds.map(id => MAPA_SERVICIOS[id]).filter(Boolean);
  }

  // Cuenta como Mantenimiento si tiene el id 5 (Mantenimiento) o el 111 (Mantenimiento - Kit IOLM)
  const haceMantenimiento = (item.specialtyIds && item.specialtyIds.some(id => IDS_MANTENIMIENTO.includes(id))) ||
    servicios.some(s => s.toLowerCase().includes('mantenimiento'));
  if (!haceMantenimiento) continue;

  // Parseamos los rangos libres una sola vez
  const rangosLibres = huecosEntrada
    .filter(r => r && r.includes('-'))
    .map(r => {
      const [ini, fin] = r.split('-').map(s => s.trim());
      return { ini: toMinutes(ini), fin: toMinutes(fin) };
    })
    .filter(r => r.ini !== null && r.fin !== null && r.fin > r.ini);

  const bloquesDisponibles = [];

  // Recorremos SIEMPRE la grilla fija en punto (08:00, 09:00, 10:00...)
  // en lugar de arrancar desde el minuto en que empieza cada hueco.
  for (
    let slotInicio = HORA_APERTURA;
    slotInicio + DURACION_TURNO_MINUTOS <= HORA_CIERRE;
    slotInicio += DURACION_TURNO_MINUTOS
  ) {
    const slotFin = slotInicio + DURACION_TURNO_MINUTOS;
    // El slot solo es válido si cae COMPLETO dentro de algún hueco libre
    const cabeEnAlgunHueco = rangosLibres.some(r => r.ini <= slotInicio && r.fin >= slotFin);
    if (cabeEnAlgunHueco) {
      bloquesDisponibles.push(`${toHHMM(slotInicio)} - ${toHHMM(slotFin)}`);
    }
  }

  if (bloquesDisponibles.length > 0) {
    resultado.push({
      json: {
        fecha,
        advisorName,
        servicios,
        huecosLibres: bloquesDisponibles
      }
    });
  }
}

return resultado;

const items = $input.all().map(i => i.json);

// ─── CONFIG: ÚNICO asesor habilitado + rango horario ──────────────────────
// Cualquier otro asesor se descarta, tenga o no slots libres.
const ASESOR_UNICO = {
  etiqueta: "MARIANO HERNANDEZ",
  ids: [164284],
  alias: ["MARIANO HERNANDEZ"],
  horaDesde: "07:30",
  horaHasta: "10:00",
};

// ─── CONFIG: asesores BLOQUEADOS ──────────────────────────────────────────
// Estos asesores NUNCA se ofrecen, tengan o no slots libres.
const ASESORES_BLOQUEADOS = [
  {
    etiqueta: "VAELLO HUGO HERNAN",
    ids: [],                                  // completar si conocés el advisorId
    alias: ["VAELLO HUGO"],                   // matchea "VAELLO HUGO HERNAN", "VAELLO, HUGO", "HUGO HERNAN VAELLO", etc.
  },
];

// ─── CONFIG: asesores CON restricción horaria ─────────────────────────────
// Solo estos tienen horarios permitidos. Cualquier otro asesor pasa sin filtro.
const ASESORES_RESTRINGIDOS = [
  {
    etiqueta: "CAMILA",
    ids: [],                                  // completar si conocés el advisorId
    alias: ["CAMILA"],
    horarios: ["08:30", "09:00", "10:30", "11:00"],
  },
  {
    etiqueta: "MELINA",
    ids: [],
    alias: ["MELINA"],
    horarios: ["08:30", "09:00", "09:30", "10:30"],
  },
  {
    etiqueta: "JUAN IGNACIO",
    ids: [151634],                            // JUAN RODRIGUEZ
    alias: ["JUAN IGNACIO"],
    horarios: ["08:30", "09:00", "10:30", "11:00"],
  },
  {
    etiqueta: "GERMAN",
    ids: [],
    alias: ["GERMAN"],
    horarios: ["08:30", "09:00", "09:30"],
  },
];
// ──────────────────────────────────────────────────────────────────────────

const normalizar = (txt = "") =>
  String(txt)
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toUpperCase()
    .replace(/[^A-Z0-9 ]/g, " ")
    .replace(/\s+/g, " ")
    .trim();

const normHora = (h) => String(h).trim().padStart(5, "0"); // "9:00" -> "09:00"

// Busca en una lista de config (bloqueados o restringidos) el asesor por id o por nombre
function buscarEnLista(item, lista) {
  const id = Number(item.advisorId);
  const porId = lista.find((a) => a.ids.includes(id));
  if (porId) return porId;

  const nombre = normalizar(item.advisorName);
  if (!nombre) return null;

  const palabras = new Set(nombre.split(" "));
  return (
    lista.find((a) =>
      a.alias.some((alias) => {
        const aliasNorm = normalizar(alias);
        if (aliasNorm === nombre) return true;
        // todas las palabras del alias deben estar en el nombre completo
        return aliasNorm.split(" ").every((p) => palabras.has(p));
      })
    ) || null
  );
}

const agrupadoPorFecha = {};

for (const item of items) {
  if (item.vacio || !Array.isArray(item.Slots_Libres) || item.Slots_Libres.length === 0) continue;

  // Solo se ofrece el asesor único
  if (!buscarEnLista(item, [ASESOR_UNICO])) continue;

  // Asesor bloqueado: no se ofrece nunca
  if (buscarEnLista(item, ASESORES_BLOQUEADOS)) continue;

  // Solo slots dentro del rango permitido
  const slots = item.Slots_Libres.map(normHora).filter(
    (s) => s >= normHora(ASESOR_UNICO.horaDesde) && s <= normHora(ASESOR_UNICO.horaHasta)
  );
  const restriccion = buscarEnLista(item, ASESORES_RESTRINGIDOS);

  // Con restricción: solo los slots habilitados. Sin restricción: todos.
  const slotsValidos = (
    restriccion
      ? slots.filter((s) => restriccion.horarios.map(normHora).includes(s))
      : slots
  ).sort();

  if (slotsValidos.length === 0) continue;

  const fecha = item.fechaActual;
  if (!agrupadoPorFecha[fecha]) {
    agrupadoPorFecha[fecha] = { fecha, asesores: [], todosLosSlotsDeLaFecha: new Set() };
  }

  agrupadoPorFecha[fecha].asesores.push({
    advisorId: item.advisorId,
    advisorName: item.advisorName,
    restringido: Boolean(restriccion),
    perfilHorario: restriccion ? restriccion.etiqueta : null,
    slotsDisponibles: slotsValidos,
    cantidadSlots: slotsValidos.length,
  });

  slotsValidos.forEach((s) => agrupadoPorFecha[fecha].todosLosSlotsDeLaFecha.add(s));
}

return Object.values(agrupadoPorFecha)
  .sort((a, b) => a.fecha.localeCompare(b.fecha))
  .map((f) => ({
    json: {
      fecha: f.fecha,
      totalAsesoresConDisponibilidad: f.asesores.length,
      slotsUnicosDelDia: Array.from(f.todosLosSlotsDeLaFecha).sort(),
      detalleAsesores: f.asesores,
    },
  }));

const fechaActual = $('Select rows from a table4').first().json.selected_date

// ─── CONFIG ───────────────────────────────────────────────────────────────
const TIPOS_QUE_OCUPAN     = ["SCHEDULED"]; // solo esto bloquea un slot
const RESPETAR_DIAS_LIBRES = true;          // daysOffs + jornada (celdas grises)
const OFRECER_SLOTS_SIN_CITA = true;        // true = "Cliente sin cita" se ofrece
// ──────────────────────────────────────────────────────────────────────────

const toMinutes = (hhmm) => {
  if (!hhmm) return null;
  const [h, m] = String(hhmm).trim().split(':').map(Number);
  return Number.isNaN(h) || Number.isNaN(m) ? null : h * 60 + m;
};
const toHHMM = (mins) =>
  `${String(Math.floor(mins / 60)).padStart(2, '0')}:${String(mins % 60).padStart(2, '0')}`;
const normHora = (h) => { const m = toMinutes(h); return m === null ? null : toHHMM(m); };

function generarSlots(entry, exit, interval) {
  const inicio = toMinutes(entry), fin = toMinutes(exit);
  if (inicio === null || fin === null || !(interval > 0)) return [];
  const slots = [];
  for (let t = inicio; t < fin; t += interval) slots.push(toHHMM(t));
  return slots;
}

const inputData = $input.first()?.json?.result?.advisorDealerSchedule;
const interval  = Number(inputData?.interval) || 30;
const advisors  = inputData?.advisors || [];

const resultado = advisors.map((a) => {
  // 1. Grilla completa de la jornada del asesor
  const gridCompleto = [
    ...generarSlots(a.amEntrance, a.amExit, interval),
    ...generarSlots(a.pmEntrance, a.pmExit, interval),
  ];

  // 2. Bloqueos por daysOffs vigentes en la fecha (celdas grises)
  const bloqueadosPorAgenda = new Set();
  if (RESPETAR_DIAS_LIBRES) {
    const offsActivos = (a.daysOffs || []).filter(
      (o) => (!o.startDay || fechaActual >= o.startDay) && (!o.endDay || fechaActual <= o.endDay)
    );
    if (offsActivos.some((o) => o.allDay)) {
      gridCompleto.forEach((s) => bloqueadosPorAgenda.add(s));
    } else {
      offsActivos.forEach((o) => {
        if (o.offStartHour && o.offEndHour) {
          generarSlots(o.offStartHour, o.offEndHour, interval).forEach((s) => bloqueadosPorAgenda.add(s));
        }
      });
    }
  }

  // 3. Ocupados REALES: solo citas del día con typeOfSchedule habilitado
  const citas = (a.dealerSchedule || []).filter(
    (c) =>
      (!c.dateSchedule || c.dateSchedule === fechaActual) &&
      TIPOS_QUE_OCUPAN.includes(String(c.typeOfSchedule || '').toUpperCase())
  );
  const ocupadosPorCita = new Set(citas.map((c) => normHora(c.hourSchedule)).filter(Boolean));

  // 4. "Cliente sin cita" (passerby): informativo, ya no bloquea
  const sinCita = new Set((a.nonScheduled || []).map((s) => normHora(s.passerbyHour)).filter(Boolean));

  const slotsLibres = gridCompleto.filter(
    (s) =>
      !bloqueadosPorAgenda.has(s) &&
      !ocupadosPorCita.has(s) &&
      (OFRECER_SLOTS_SIN_CITA || !sinCita.has(s))
  );

  const ordenar = (arr) => Array.from(arr).sort((x, y) => toMinutes(x) - toMinutes(y));

  return {
    json: {
      fechaActual,
      advisorId: a.advisorId,
      advisorName: String(a.advisorName || '').replace(/\s+/g, ' ').trim(),
      Slots_Libres: slotsLibres,
      Cantidad_Slots_Libres: slotsLibres.length,
      // apoyo / debug
      Slots_Ocupados: ordenar(ocupadosPorCita),
      Slots_FueraDeAgenda: ordenar(bloqueadosPorAgenda),
      Slots_SinCita: ordenar(sinCita).filter((s) => gridCompleto.includes(s)),
      Jornada: { amEntrance: a.amEntrance, amExit: a.amExit, pmEntrance: a.pmEntrance, pmExit: a.pmExit, interval },
    },
  };
});

if (resultado.length === 0) {
  return [{ json: { fechaActual, vacio: true, Slots_Libres: [], Cantidad_Slots_Libres: 0 } }];
}
return resultado;

// ==========================================================
// Turno ofrecido - Buscar el turno que eligió el cliente
// (misma fecha, misma hora y mismo asesor que se le ofreció)
// ==========================================================

function toMinutes(hhmm) {
  if (hhmm === null || hhmm === undefined) return null;
  const match = String(hhmm).match(/(\d{1,2})[:.](\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function normalizarTexto(str) {
  return String(str ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normFecha(v) {
  if (!v) return null;
  const m = String(v).match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : null;
}

// ---------- Configuración ----------
const DURACION_SERVICIO_MINUTOS = 60;
const DIFERENCIA_MAXIMA_MINUTOS = 60;
// Si no se puede identificar al asesor (id/nombre vacío o distinto),
// usar el asesor que tenga libre ese horario ese día.
const USAR_FALLBACK_POR_HORARIO = true;

// ---------- Turno elegido por el cliente ----------
const fila = $('Select rows from a table4').first().json;
let trigger = {};
try { trigger = $('When Executed by Another Workflow').first().json || {}; } catch (e) {}

const fechaElegida = normFecha(fila.selected_date);
const minHoraElegida = toMinutes(fila.selected_hour);

// El asesor puede venir con distintos nombres de campo, en la fila o en el trigger
const CAMPOS_ID = ['advisorId', 'advisor_id', 'asesorId', 'asesor_id', 'idAsesor', 'id_asesor', 'selected_advisor_id'];
const CAMPOS_NOMBRE = ['nombre_asesor', 'asesor', 'asesorNombre', 'advisorName', 'advisor_name', 'selected_advisor', 'nombreAsesor'];

const idsBuscados = [...new Set(
  [fila, trigger].flatMap(o => CAMPOS_ID.map(k => o?.[k]))
    .filter(v => v !== null && v !== undefined && String(v).trim() !== '' && String(v) !== '0')
    .map(v => String(v).trim())
)];
const nombresBuscados = [...new Set(
  [fila, trigger].flatMap(o => CAMPOS_NOMBRE.map(k => o?.[k]))
    .filter(v => typeof v === 'string')
    .map(normalizarTexto)
    .filter(Boolean)
)];

function coincideNombre(nombreAsesor, buscado) {
  const a = normalizarTexto(nombreAsesor);
  if (!a || !buscado) return false;
  if (a === buscado) return true;
  // "camila" / "arredondo camila" vs "camila arredondo": todas las palabras del más corto están en el otro
  const pa = new Set(a.split(' '));
  const pb = new Set(buscado.split(' '));
  const [chico, grande] = pa.size <= pb.size ? [pa, pb] : [pb, pa];
  return [...chico].every(p => grande.has(p));
}

function esAsesorElegido(asesor) {
  if (idsBuscados.includes(String(asesor.advisorId))) return true;
  return nombresBuscados.some(n => coincideNombre(asesor.advisorName, n));
}

// ---------- Separar items que llegan desde el Merge ----------
const itemsCombinados = $input.all().map(i => i.json);

const listaAsesores = itemsCombinados.filter(item => Array.isArray(item.detalleAsesores));
const listaMecanicos = itemsCombinados.filter(item =>
  !Array.isArray(item.detalleAsesores) && (item.huecosLibres || item.Huecos_Libres || item.servicios || item.specialtyIds)
);

// Todos los asesores del día elegido (puede haber más de un item por fecha)
const asesoresDelDia = listaAsesores
  .filter(d => normFecha(d.fecha || d.fechaActual) === fechaElegida)
  .flatMap(d => d.detalleAsesores || []);

// Asesores que tienen libre EXACTAMENTE la hora elegida
const asesoresConEseHorario = asesoresDelDia.filter(a =>
  (a.slotsDisponibles || []).some(s => toMinutes(s) === minHoraElegida)
);

// Mecánicos de Mantenimiento disponibles en la fecha elegida
const mecanicosDelDia = [];
for (const m of listaMecanicos) {
  if (normFecha(m.fecha || m.fechaActual) !== fechaElegida) continue;

  const servicios = (m.servicios || []).map(normalizarTexto);
  const specialtyIds = (m.specialtyIds || []).map(Number);
  const haceMantenimiento =
    specialtyIds.includes(5) || specialtyIds.includes(111) || servicios.some(s => s.includes('mantenimiento'));
  if (!haceMantenimiento) continue;

  const intervalos = [];
  (m.huecosLibres || m.Huecos_Libres || []).forEach(rango => {
    const partes = String(rango).split(/[-–—]/).map(s => s.trim());
    if (partes.length === 2) {
      const ini = toMinutes(partes[0]);
      const fin = toMinutes(partes[1]);
      if (ini !== null && fin !== null && fin > ini) intervalos.push([ini, fin]);
    }
  });
  if (intervalos.length) mecanicosDelDia.push({ nombre: m.advisorName, intervalos });
}

function buscarMecanico(minRecepcion) {
  for (const mec of mecanicosDelDia) {
    for (const [iniMec, finMec] of mec.intervalos) {
      const inicioAtencion = Math.max(minRecepcion, iniMec);
      const finAtencion = inicioAtencion + DURACION_SERVICIO_MINUTOS;
      const diferenciaEspera = inicioAtencion - minRecepcion;
      if (diferenciaEspera <= DIFERENCIA_MAXIMA_MINUTOS && finAtencion <= finMec) {
        return { mec, inicioAtencion, finAtencion, diferenciaEspera };
      }
    }
  }
  return null;
}

// ---------- Elegir el asesor ----------
// 1) El asesor identificado (id o nombre) que tenga libre esa hora
let asesor = asesoresConEseHorario.find(esAsesorElegido) || null;
let asesorInferido = false;

// 2) Fallback: no se pudo identificar, pero el horario está libre para algún asesor
if (!asesor && USAR_FALLBACK_POR_HORARIO && asesoresConEseHorario.length > 0) {
  const asesorIdentificadoSinEseHorario = asesoresDelDia.find(esAsesorElegido);
  // Solo si NO hay un asesor identificado que tenga el día pero no esa hora
  if (!asesorIdentificadoSinEseHorario) {
    asesor = asesoresConEseHorario[0];
    asesorInferido = true;
  }
}

let turno = null;
if (asesor && minHoraElegida !== null) {
