  6:  1408,   // 6ª
  7:  1409,   // 7ª
  8:  1410,   // 8ª
  9:  1411,   // 9ª
  10: 1412,   // 10ª
  11: 1413,   // 11ª
  12: 1414,   // 12ª
  13: 1415,   // 13ª
  14: 1416,   // 14ª
  15: 1417,   // 15ª
  16: 1418,   // 16ª
  17: 1419    // 17ª 
};

const serviceId = SERVICIOS[serviceNumber] || (1402 + serviceNumber);

return [
  {
    json: {
      km_original: kmRaw,
      km_redondeado: kmRedondeado,
      km_frequency: kmFrequency,
      service_number: serviceNumber,
      service_id: serviceId,
      months,
    }
  }
];

