function toMinutes(hhmm) {
  if (hhmm === null || hhmm === undefined) return null;
  const match = String(hhmm).match(/(\d{1,2})[:.](\d{2})/);
  if (!match) return null;
  return parseInt(match[1], 10) * 60 + parseInt(match[2], 10);
}

function toHHMM(mins) {
  const h = String(Math.floor(mins / 60)).padStart(2, '0');
  const m = String(mins % 60).padStart(2, '0');
  return `${h}:${m}`;
}

function normalizarTexto(str) {
  return String(str ?? '')
    .normalize('NFD')
    .replace(/[̀-ͯ]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9 ]/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function normFecha(v) {
  if (!v) return null;
  const m = String(v).match(/\d{4}-\d{2}-\d{2}/);
  return m ? m[0] : null;
}

// ---------- Configuración ----------
const DURACION_SERVICIO_MINUTOS = 60;
const DIFERENCIA_MAXIMA_MINUTOS = 60;
// Si no se puede identificar al asesor (id/nombre vacío o distinto),
// usar el asesor que tenga libre ese horario ese día.
const USAR_FALLBACK_POR_HORARIO = true;

// ---------- Turno elegido por el cliente ----------
const fila = $('Select rows from a table4').first().json;
let trigger = {};
try { trigger = $('When Executed by Another Workflow').first().json || {}; } catch (e) {}

const fechaElegida = normFecha(fila.selected_date);
const minHoraElegida = toMinutes(fila.selected_hour);

// El asesor puede venir con distintos nombres de campo, en la fila o en el trigger
const CAMPOS_ID = ['advisorId', 'advisor_id', 'asesorId', 'asesor_id', 'idAsesor', 'id_asesor', 'selected_advisor_id'];
const CAMPOS_NOMBRE = ['nombre_asesor', 'asesor', 'asesorNombre', 'advisorName', 'advisor_name', 'selected_advisor', 'nombreAsesor'];

const idsBuscados = [...new Set(
  [fila, trigger].flatMap(o => CAMPOS_ID.map(k => o?.[k]))
    .filter(v => v !== null && v !== undefined && String(v).trim() !== '' && String(v) !== '0')
    .map(v => String(v).trim())
)];
const nombresBuscados = [...new Set(
  [fila, trigger].flatMap(o => CAMPOS_NOMBRE.map(k => o?.[k]))
    .filter(v => typeof v === 'string')
    .map(normalizarTexto)
    .filter(Boolean)
)];

function coincideNombre(nombreAsesor, buscado) {
  const a = normalizarTexto(nombreAsesor);
  if (!a || !buscado) return false;
  if (a === buscado) return true;
  // "camila" / "arredondo camila" vs "camila arredondo": todas las palabras del más corto están en el otro
  const pa = new Set(a.split(' '));
  const pb = new Set(buscado.split(' '));
  const [chico, grande] = pa.size <= pb.size ? [pa, pb] : [pb, pa];
  return [...chico].every(p => grande.has(p));
}

function esAsesorElegido(asesor) {
  if (idsBuscados.includes(String(asesor.advisorId))) return true;
  return nombresBuscados.some(n => coincideNombre(asesor.advisorName, n));
}

